/**
 * The text a Connected or Cancel click sends as the person's next message, in
 * Slack and the playground. The engine reads it back at turn start. The
 * playground keeps a copy, `playground/src/lib/connect-click.ts`, that must match.
 */
export function connectClickText(connection, decision) {
    return decision === "approve"
        ? `I connected ${connection}. Continue my request.`
        : `I won't connect ${connection} now. Continue without it.`;
}
/** The click a message is, for one of `connections`, or undefined for any other text. */
export function parseConnectClickText(message, connections) {
    const text = message.trim();
    for (const connection of connections) {
        for (const decision of ["approve", "deny"]) {
            if (text === connectClickText(connection, decision)) {
                return { connection, decision };
            }
        }
    }
    return undefined;
}
